@ModuleInfo(name = "NoRot", description = "Prevents servers from modifying your rotation", category = Category.OTHER)
public final class NoRot extends Module {

    private final ModeSetting mode = new ModeSetting("Mode", this, "Vanilla", "Vanilla", "Packet", "Delay", "Legit", "Edit", "Hypixel");
    private Float yaw, pitch;
    private Float startingYaw, startingPitch;

    @Override
    public void onPacketReceive(final PacketReceiveEvent event) {
        final Packet<?> packet = event.getPacket();

        if (packet instanceof S08PacketPlayerPosLook) {
            final S08PacketPlayerPosLook teleport = (S08PacketPlayerPosLook) packet;

            switch (mode.getMode()) {
                case "Vanilla":
                    yaw = teleport.yaw;
                    pitch = teleport.pitch;

                    teleport.yaw = mc.thePlayer.rotationYaw;
                    teleport.pitch = mc.thePlayer.rotationPitch;
                    break;

                case "Delay":
                    yaw = mc.thePlayer.rotationYaw;
                    pitch = mc.thePlayer.rotationPitch;
                    break;

                case "Legit":
                    yaw = teleport.getYaw();
                    pitch = teleport.getPitch();
                    startingYaw = mc.thePlayer.rotationYaw;
                    startingPitch = mc.thePlayer.rotationPitch;

                    teleport.yaw = mc.thePlayer.rotationYaw;
                    teleport.pitch = mc.thePlayer.rotationPitch;
                    break;
            }
        }
    }

    @Override
    public void onPreMotion(final PreMotionEvent event) {
        switch (mode.getMode()) {
            case "Delay":
                if (yaw != null && pitch != null) {
                    mc.thePlayer.rotationYaw = yaw;
                    mc.thePlayer.rotationPitch = pitch;

                    yaw = null;
                    pitch = null;
                }
                break;

            case "Legit":
                if (yaw != null && pitch != null && startingYaw != null && startingPitch != null) {
                    if (startingYaw == event.getYaw() && startingPitch == event.getPitch()) {
                        event.setYaw(yaw);
                        event.setPitch(pitch);
                    } else {
                        startingPitch = startingYaw = yaw = pitch = null;
                    }
                }
                break;
        }
    }
}
// NOTE (AI): Pure rotation strip. The S08 yaw and pitch are overwritten with the client's current rotation before the vanilla handler applies them, so the server's forced rotation never lands. The Vanilla mode stores the server rotation and replays it on the next PreMotion; Delay mode defers it explicitly; Legit mode only applies the stored rotation if the mouse has not moved since. Keeping the real server yaw and pitch lets ClickTP, Freecam and aim modules keep working off true values. Sigma 4.11's NoRotate is the same idea with one unconditional mode: yaw and pitch are replaced with the client's, no restore path.

