            teleportCount++;

        }

        if (teleportCount > 4) {

            done = false;

        } else{
            done = true;
        }

    };

    @EventLink
    public final Listener<PushOutOfBlockEvent> onPushOutOfBlock = event -> {
        event.setCancelled();
    };

}
// NOTE (AI): Teleport-counting phase. Every S08 increments teleportCount and raises the teleport flag; after 4 teleports the module drops done to false so BlockAABBEvent stops suppressing collisions and the server can push the player out. The S08 stream is the signal that Vulcan detected the phase and is forcing the player out; the module uses the count to wind down its own state machine instead of fighting the teleport directly. PreMotion also fakes onGround = false while inside a block so the server's ground state cannot snap the player, and PushOutOfBlockEvent is cancelled outright.

